DO $$DECLARE c UUID;t JSONB;tid UUID;BEGIN c:=public.catalogue_save_category(jsonb_build_object('code','RT_CAT','name','Runtime Category','description','rollback','display_order',999),NULL);t:=public.catalogue_save_test(jsonb_build_object('code','RT_TEST','name','Runtime Test','short_name','RT','description','rollback','category_id',c,'department','Runtime','category','Runtime Category','test_kind','Individual','reporting_type','NoReporting','price_paisa',10000,'sample_type','','container','','tat_hours',1,'display_order',999,'price_configured',TRUE,'allow_zero_price_billing',FALSE,'pricing_policy','Fixed','search_aliases','[]'::JSONB,'clinical_configuration_status','Configured','workflow_supported',TRUE),NULL);tid:=(t->>'id')::UUID;PERFORM set_config('runtime.test_id',tid::TEXT,TRUE);PERFORM set_config('runtime.category_id',c::TEXT,TRUE);PERFORM pg_temp.ok(11,'Technician add test',tid IS NOT NULL);END$$;
SELECT pg_temp.ok(63,'new catalogue test enters readiness workflow',EXISTS(SELECT 1 FROM public.catalogue_readiness_inventory(NULL,'RT_TEST') AS x(value) WHERE x.value->>'test_id'=current_setting('runtime.test_id')));
DO $$DECLARE tid UUID:=current_setting('runtime.test_id')::UUID;v BIGINT;t JSONB;BEGIN SELECT row_version INTO v FROM public.tests WHERE id=tid;t:=public.catalogue_save_test((SELECT to_jsonb(x)||jsonb_build_object('name','Runtime Test Edited','category_id',category_id,'search_aliases','[]'::JSONB) FROM public.tests x WHERE id=tid),v);PERFORM pg_temp.ok(12,'Technician edit test',(SELECT name='Runtime Test Edited' FROM public.tests WHERE id=tid));END$$;
DO $$DECLARE tid UUID:=current_setting('runtime.test_id')::UUID;r JSONB;BEGIN r:=public.catalogue_set_current_rate('Test',tid,12500,NULL,NULL,'runtime update');PERFORM pg_temp.ok(13,'Technician update rate',(r->>'price_paisa')::BIGINT=12500);END$$;
SELECT pg_temp.ok(14,'Technician category CRUD',(SELECT name='Runtime Category' FROM public.test_categories WHERE id=current_setting('runtime.category_id')::UUID));
DO $$DECLARE pid UUID;BEGIN pid:=public.catalogue_save_parameter(jsonb_build_object('test_id',current_setting('runtime.test_id'),'code','RTP','name','Runtime Parameter','value_type','Numeric','unit','mg/dL','display_order',1,'is_mandatory',TRUE,'is_active',TRUE,'decimal_precision',2,'calculation_identifier',NULL,'option_set_id',NULL),NULL);PERFORM set_config('runtime.parameter_id',pid::TEXT,TRUE);PERFORM pg_temp.ok(15,'Technician parameter CRUD',pid IS NOT NULL);END$$;
DO $$DECLARE rid UUID;BEGIN rid:=public.catalogue_save_range(jsonb_build_object('parameter_id',current_setting('runtime.parameter_id'),'gender','All','age_min_days',0,'age_max_days',50000,'normal_min',10,'normal_max',20,'critical_low',5,'critical_high',30,'normal_text',NULL,'method','Runtime','unit','mg/dL'),NULL);PERFORM set_config('runtime.range_id',rid::TEXT,TRUE);PERFORM pg_temp.ok(16,'Technician range CRUD',rid IS NOT NULL);PERFORM pg_temp.ok(17,'Technician critical range',(SELECT critical_low=5 AND critical_high=30 FROM public.reference_ranges WHERE id=rid));END$$;
DO $$DECLARE p UUID;v BIGINT;BEGIN p:=public.catalogue_save_panel(jsonb_build_object('code','RT_PANEL','name','Runtime Panel','category_id',current_setting('runtime.category_id'),'display_order',999),NULL);SELECT row_version INTO v FROM public.catalogue_panels WHERE id=p;PERFORM public.catalogue_save_panel_component(p,current_setting('runtime.test_id')::UUID,NULL,'Runtime Test',1,v);PERFORM set_config('runtime.panel_id',p::TEXT,TRUE);PERFORM pg_temp.ok(18,'Technician panel/profile CRUD',p IS NOT NULL);SELECT row_version INTO v FROM public.catalogue_panels WHERE id=p;PERFORM public.catalogue_reorder_panel_components(p,ARRAY[current_setting('runtime.test_id')::UUID],v);PERFORM pg_temp.ok(19,'Technician membership reorder',TRUE);END$$;
DO $$DECLARE tid UUID:=current_setting('runtime.test_id')::UUID;v BIGINT;s JSONB;BEGIN SELECT row_version INTO v FROM public.tests WHERE id=tid;s:=public.catalogue_set_test_lifecycle(tid,'Active',v);SELECT row_version INTO v FROM public.tests WHERE id=tid;s:=public.catalogue_set_test_lifecycle(tid,'Draft',v);PERFORM pg_temp.ok(20,'Technician activation/deactivation',(s->>'status')='Draft');END$$;
DO $$DECLARE t JSONB;tid UUID;v BIGINT;BEGIN t:=public.catalogue_save_test(jsonb_build_object('code','RT_DELETE','name','Runtime Delete','category_id',current_setting('runtime.category_id'),'department','Runtime','category','Runtime Category','test_kind','Individual','reporting_type','NoReporting','price_paisa',100,'sample_type','','container','','tat_hours',1,'display_order',1000,'price_configured',TRUE,'pricing_policy','Fixed','search_aliases','[]'::JSONB,'clinical_configuration_status','Configured','workflow_supported',TRUE),NULL);tid:=(t->>'id')::UUID;SELECT row_version INTO v FROM public.tests WHERE id=tid;PERFORM public.catalogue_delete_test(tid,v);PERFORM pg_temp.ok(21,'Technician unused delete',NOT EXISTS(SELECT 1 FROM public.tests WHERE id=tid));END$$;
