RESET ROLE;INSERT INTO public.tests(id,code,name,department,category,reporting_type,price_paisa,sample_type,container,is_active,display_order,allow_manual_price,price_configured,pricing_policy,lifecycle_status,billing_enabled,clinical_reporting_enabled,collection_required,workflow_supported,clinical_configuration_status,category_id)
VALUES('97300000-0000-0000-0000-000000000001','RT_BILL_FIXED','Runtime Billing Fixed','Runtime','Runtime','NoReporting',60000,'','','true',9990,FALSE,TRUE,'Fixed','Active',TRUE,FALSE,FALSE,TRUE,'Configured',current_setting('runtime.category_id')::UUID),
('97300000-0000-0000-0000-000000000002','RT_BILL_OPEN','Runtime Billing Open','Runtime','Runtime','NoReporting',0,'','','true',9991,FALSE,FALSE,'PricePending','Active',TRUE,FALSE,FALSE,TRUE,'Configured',current_setting('runtime.category_id')::UUID);
SET LOCAL ROLE authenticated;SELECT set_config('request.jwt.claim.sub','97000000-0000-0000-0000-000000000002',TRUE);
CREATE OR REPLACE FUNCTION pg_temp.bill(test_id UUID,rate BIGINT,key TEXT,paid BIGINT DEFAULT 0,discount BIGINT DEFAULT 0)RETURNS JSONB LANGUAGE plpgsql AS $$DECLARE t public.tests%ROWTYPE;BEGIN SELECT * INTO t FROM public.tests WHERE id=test_id;RETURN public.create_patient_bill_order_with_packages(jsonb_build_object('mobile','98'||lpad((abs(hashtext(key))%100000000)::TEXT,8,'0'),'full_name','Runtime Billing Patient','gender','Other','age_years',30,'age_months',0,'age_days',0,'address','Runtime'),jsonb_build_object('gross_amount_paisa',rate,'discount_amount_paisa',discount,'paid_amount_paisa',paid,'order_date_bs','2083-05-15','remarks','runtime'),ARRAY[jsonb_build_object('test_id',t.id,'unit_price_paisa',rate,'manual_price_paisa',rate,'discount_paisa',discount,'zero_price_acknowledged',FALSE)],CASE WHEN paid>0 THEN jsonb_build_object('payment_mode','Cash','received_by_name','Runtime Technician') END,key,'[]');END$$;
DO $$DECLARE r JSONB;BEGIN r:=pg_temp.bill('97300000-0000-0000-0000-000000000001',60000,'rt-default');PERFORM pg_temp.ok(27,'configured default rate',(r->>'gross_amount_paisa')::BIGINT=60000);r:=pg_temp.bill('97300000-0000-0000-0000-000000000001',55000,'rt-lower');PERFORM pg_temp.ok(28,'configured rate edited lower',(r->>'gross_amount_paisa')::BIGINT=55000);r:=pg_temp.bill('97300000-0000-0000-0000-000000000001',65000,'rt-higher');PERFORM pg_temp.ok(29,'configured rate edited higher',(r->>'gross_amount_paisa')::BIGINT=65000);r:=pg_temp.bill('97300000-0000-0000-0000-000000000002',60000,'rt-open');PERFORM pg_temp.ok(30,'unconfigured plus valid agreed rate',(r->>'gross_amount_paisa')::BIGINT=60000);END$$;
DO $$BEGIN BEGIN PERFORM pg_temp.bill('97300000-0000-0000-0000-000000000002',NULL,'rt-missing');RAISE EXCEPTION 'missing accepted';EXCEPTION WHEN OTHERS THEN PERFORM pg_temp.ok(31,'unconfigured missing rate denied',TRUE);END;BEGIN PERFORM pg_temp.bill('97300000-0000-0000-0000-000000000002',0,'rt-zero');RAISE EXCEPTION 'zero accepted';EXCEPTION WHEN OTHERS THEN PERFORM pg_temp.ok(32,'zero rate behavior',TRUE);END;BEGIN PERFORM pg_temp.bill('97300000-0000-0000-0000-000000000002',-1,'rt-negative');RAISE EXCEPTION 'negative accepted';EXCEPTION WHEN OTHERS THEN PERFORM pg_temp.ok(33,'negative rate denied',TRUE);END;END$$;
SELECT pg_temp.ok(34,'panel default rate',EXISTS(SELECT 1 FROM public.catalogue_rate_versions WHERE panel_service_id IS NOT NULL AND status='Active'));
SELECT pg_temp.ok(35,'panel edited agreed rate',pg_get_functiondef('public.create_patient_bill_order_with_panel_service(jsonb,jsonb,jsonb,text,uuid,bigint,bigint)'::regprocedure) LIKE '%p_agreed_panel_price_paisa%');
SELECT pg_temp.ok(36,'migration 00086 panel regression',NOT has_function_privilege('authenticated','public.create_patient_bill_order_with_panel_service(jsonb,jsonb,jsonb,text,uuid,bigint)','EXECUTE'));
DO $$DECLARE a JSONB;b JSONB;BEGIN a:=pg_temp.bill('97300000-0000-0000-0000-000000000001',61000,'rt-mixed-a');b:=pg_temp.bill('97300000-0000-0000-0000-000000000002',62000,'rt-mixed-b');PERFORM pg_temp.ok(37,'mixed configured/manual bill',a IS NOT NULL AND b IS NOT NULL);a:=pg_temp.bill('97300000-0000-0000-0000-000000000001',60000,'rt-paid',60000);PERFORM pg_temp.ok(38,'full payment',(a->>'payment_status')='Paid');a:=pg_temp.bill('97300000-0000-0000-0000-000000000001',60000,'rt-partial',30000);PERFORM pg_temp.ok(39,'partial payment',(a->>'payment_status')='Partial');END$$;
SELECT pg_temp.ok(40,'discount',pg_temp.bill('97300000-0000-0000-0000-000000000001',60000,'rt-discount',0,1000) IS NOT NULL);
DO $$DECLARE a JSONB;b JSONB;before_count BIGINT;BEGIN a:=pg_temp.bill('97300000-0000-0000-0000-000000000001',60000,'rt-idempotent');b:=pg_temp.bill('97300000-0000-0000-0000-000000000001',60000,'rt-idempotent');PERFORM pg_temp.ok(41,'idempotent duplicate submission',(b->>'idempotency_replay')::BOOLEAN);SELECT count(*) INTO before_count FROM public.bills;BEGIN PERFORM pg_temp.bill('97300000-0000-0000-0000-000000000002',-50,'rt-rollback');EXCEPTION WHEN OTHERS THEN NULL;END;PERFORM pg_temp.ok(42,'rollback on validation failure',(SELECT count(*)=before_count FROM public.bills));PERFORM public.catalogue_set_current_rate('Test','97300000-0000-0000-0000-000000000001',70000,NULL,NULL,'future default');PERFORM pg_temp.ok(43,'historical bill unchanged after rate update',EXISTS(SELECT 1 FROM public.bill_items WHERE bill_id=(a->>'bill_id')::UUID AND unit_price_paisa=60000));END$$;

