DO $$BEGIN BEGIN PERFORM public.update_user_access('97000000-0000-0000-0000-000000000001',TRUE,FALSE,ARRAY[]::UUID[]);RAISE EXCEPTION 'owner mutation accepted';EXCEPTION WHEN insufficient_privilege THEN PERFORM pg_temp.ok(58,'Technician cannot mutate Super Admin state',TRUE);END;END$$;
SELECT pg_temp.ok(59,'machine identities cannot acquire staff role',NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id IN('97000000-0000-0000-0000-000000000004','97000000-0000-0000-0000-000000000005')));
DO $$DECLARE patient_id UUID; history_count INT;BEGIN SELECT p.id INTO patient_id FROM public.patients p WHERE p.full_name='Runtime Billing Patient' ORDER BY p.created_at LIMIT 1;SELECT count(*) INTO history_count FROM public.search_patient_history(patient_id,'bills',NULL,NULL,26);PERFORM pg_temp.ok(60,'patient bill history runtime contract',history_count>=1);END$$;
DO $$DECLARE rate_id UUID;version BIGINT;outcome TEXT;BEGIN SELECT id,row_version INTO rate_id,version FROM public.catalogue_rate_versions WHERE test_id='97300000-0000-0000-0000-000000000001' AND status='Active' ORDER BY version_number DESC LIMIT 1;outcome:=public.catalogue_delete_or_archive_rate(rate_id,version);PERFORM pg_temp.ok(61,'rate archive enum runtime contract',outcome='Archived' AND EXISTS(SELECT 1 FROM public.catalogue_rate_versions WHERE id=rate_id AND status='Archived'));END$$;
DO $$DECLARE test_id UUID:='97300000-0000-0000-0000-000000000001';version BIGINT;next_version BIGINT;state_after TEXT;BEGIN SELECT (x.value->>'configuration_version')::BIGINT INTO version FROM public.catalogue_readiness_inventory(NULL,'RT_BILL_FIXED') AS x(value) WHERE x.value->>'test_id'=test_id::TEXT;next_version:=public.catalogue_decide_readiness(test_id,'Suspend','runtime operational catalogue decision',version);SELECT x.value->>'approval_state' INTO state_after FROM public.catalogue_readiness_inventory('Suspended','RT_BILL_FIXED') AS x(value) WHERE x.value->>'test_id'=test_id::TEXT;PERFORM pg_temp.ok(62,'Technician catalogue readiness decision',next_version=version+1 AND state_after='Suspended');END$$;
